// TickChildren ticks child state machines (W3C SCXML 6.4).
// Port of Rust do_tick_children().
func (p *StaticInvokeStringPolicy) TickChildren(engine *sce.Engine[StaticInvokeStringState, StaticInvokeStringEvent]) {
	if !p.pendingDoneInvokeFits && p.childFits != nil {
		child := p.childFits
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "fits", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "fits", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeFits {
			p.pendingDoneInvokeFits = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("fits", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeOver && p.childOver != nil {
		child := p.childOver
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "over", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "over", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeOver {
			p.pendingDoneInvokeOver = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("over", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeWide && p.childWide != nil {
		child := p.childWide
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "wide", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "wide", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeWide {
			p.pendingDoneInvokeWide = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("wide", child.DonedataAtFinal(), engine)
		}
	}
}

// SettleChildren settles what every running child sent this machine while it was
// driven by a delivery (sce.ChildSettler; docs/adr/0045): the events it sent
// `#_parent` are raised here, and a child that reached its final state raises
// `done.invoke` once. One body for every drive of a child, so a save at any
// boundary of this session finds the child's buffer empty.
func (p *StaticInvokeStringPolicy) SettleChildren(engine *sce.Engine[StaticInvokeStringState, StaticInvokeStringEvent]) {
	if child := p.childFits; child != nil && !p.pendingDoneInvokeFits {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "fits", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeFits = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("fits", child.DonedataAtFinal(), engine)
		}
	}
	if child := p.childOver; child != nil && !p.pendingDoneInvokeOver {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "over", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeOver = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("over", child.DonedataAtFinal(), engine)
		}
	}
	if child := p.childWide; child != nil && !p.pendingDoneInvokeWide {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "wide", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeWide = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("wide", child.DonedataAtFinal(), engine)
		}
	}
}

// AdoptHostInvokersInChildren hands the tree's host invokers on to every child
// this machine holds now (sce.HostInvokeChildren; docs/adr/0045): a child a
// restore resumed holds children of its own, resumed with it before its parent
// could hand it anything.
func (p *StaticInvokeStringPolicy) AdoptHostInvokersInChildren(invokers *sce.TreeInvokers) {
	if tree, ok := p.childFits.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
	if tree, ok := p.childOver.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
	if tree, ok := p.childWide.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
}

// RouteHostInvokeEndToChild delivers the ending of a host-run invocation to the
// child at or below which the session sessionID is (sce.HostInvokeChildren), and
// answers false when no running child holds it.
func (p *StaticInvokeStringPolicy) RouteHostInvokeEndToChild(sessionID string, ending sce.HostInvokeEnding) (bool, error) {
	if tree, ok := p.childFits.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	if tree, ok := p.childOver.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	if tree, ok := p.childWide.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	return false, nil
}

// NextChildDeadline reports the nearest deadline among the running children
// (W3C SCXML 6.4), so a host that walks time by TimeUntilNextScheduled does not
// step over a timer a child armed. The ticking above is what makes it this
// machine's. A child that has ended (pendingDoneInvoke) is skipped: the policy
// keeps it until its state exits, and what it armed is no longer owed.
func (p *StaticInvokeStringPolicy) NextChildDeadline() (time.Duration, bool) {
	var soonest time.Duration
	found := false
	if !p.pendingDoneInvokeFits && p.childFits != nil {
		if due, ok := p.childFits.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeOver && p.childOver != nil {
		if due, ok := p.childOver.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeWide && p.childWide != nil {
		if due, ok := p.childWide.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	return soonest, found
}


// DeliverToInvocation delivers a delayed `<send target="#_<invokeid>">` whose
// wait is over, by name — a child need not declare every event its parent
// sends (W3C SCXML 6.2 + 6.4). It answers whether the invocation was there to
// take it: one whose session has reached its final state has ended, and the
// engine reports the send it could not deliver (W3C SCXML C.1).
func (p *StaticInvokeStringPolicy) DeliverToInvocation(invokeID, eventName, eventData, sendID string) bool {
	if invokeID == "fits" {
		if child := p.childFits; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	if invokeID == "over" {
		if child := p.childOver; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	if invokeID == "wide" {
		if child := p.childWide; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	return false
}

// IsInvocationRunning reports whether `#_<invokeid>` names an invocation running
// now (W3C SCXML 6.4 + C.1) — one whose session has reached its final state has
// ended, and a send naming it is reported when it is made.
func (p *StaticInvokeStringPolicy) IsInvocationRunning(invokeID string) bool {
	if invokeID == "fits" {
		child := p.childFits
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "over" {
		child := p.childOver
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "wide" {
		child := p.childWide
		return child != nil && !child.IsInFinalState()
	}
	return false
}

// IsChildSessionRunning reports whether a session id names a child of this
// machine that is running now (W3C SCXML C.1) — the test DeliverToChildSession
// makes.
func (p *StaticInvokeStringPolicy) IsChildSessionRunning(childSessionID string) bool {
	if childSessionID == "" {
		return false
	}
	if cs, ok := p.activeInvokes["fits"]; ok && cs.SessionID == childSessionID {
		child := p.childFits
		return child != nil && !child.IsInFinalState()
	}
	if cs, ok := p.activeInvokes["over"]; ok && cs.SessionID == childSessionID {
		child := p.childOver
		return child != nil && !child.IsInFinalState()
	}
	if cs, ok := p.activeInvokes["wide"]; ok && cs.SessionID == childSessionID {
		child := p.childWide
		return child != nil && !child.IsInFinalState()
	}
	return false
}

// DeliverToChildSession delivers an event addressed to a child's published
// location (W3C SCXML C.1).
//
// The parent mints `parentSession.invokeId` for each child and that id is what
// the child's `_ioprocessors` entry names, so a <send> whose target decodes to
// one of them is addressed to that child rather than to this machine. A false
// return means the address names no live child of ours and the event takes the
// normal external path — the routing half of C.1 is what makes the published
// location a usable target rather than a string that merely compares equal.
func (p *StaticInvokeStringPolicy) DeliverToChildSession(childSessionID, eventName, eventData string) bool {
	if !p.IsChildSessionRunning(childSessionID) {
		return false
	}
	if cs, ok := p.activeInvokes["fits"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childFits, eventName, eventData)
		return true
	}
	if cs, ok := p.activeInvokes["over"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childOver, eventName, eventData)
		return true
	}
	if cs, ok := p.activeInvokes["wide"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childWide, eventName, eventData)
		return true
	}
	return false
}


